#include <utility>
#include <vector>

std::pair<long long, int> read_and_solve_college() {
    int n;
    std::cin >> n;
    std::vector<int> maximum(n);
    for (int i = 0; i < n; ++i) std::cin >> maximum[i];
    std::sort(maximum.begin(), maximum.end());
    long long best_money = -1;
    int best_tuition = 0;
    for (int i = 0; i < n; ++i) {
        if (i > 0 && maximum[i] == maximum[i - 1]) continue;
        const long long money = static_cast<long long>(maximum[i]) * (n - i);
        if (money > best_money) {
            best_money = money;
            best_tuition = maximum[i];
        }
    }
    return std::make_pair(best_money, best_tuition);
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(NULL);
    const std::pair<long long, int> result = read_and_solve_college();
    std::cout << result.first << ' ' << result.second << '\n';
    return 0;
}
