#include <algorithm>
#include <iostream>
#include <string>

struct FeedResult {
    int count;
    std::string patches;
};

FeedResult solve_feeding_case(int n, int k, const std::string& breed) {
    FeedResult answer = {0, std::string(n, '.')};
    int covered_until[2] = {-1, -1};
    for (int i = 0; i < n; ++i) {
        const int type = breed[i] == 'G' ? 0 : 1;
        if (i <= covered_until[type]) continue;
        int position = std::min(n - 1, i + k);
        if (answer.patches[position] != '.') --position;
        answer.patches[position] = breed[i];
        covered_until[type] = std::min(n - 1, position + k);
        ++answer.count;
    }
    return answer;
}

void read_and_solve_feeding() {
    int tests;
    std::cin >> tests;
    while (tests--) {
        int n, k;
        std::string breed;
        std::cin >> n >> k >> breed;
        const FeedResult answer = solve_feeding_case(n, k, breed);
        std::cout << answer.count << '\n' << answer.patches << '\n';
    }
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(NULL);
    read_and_solve_feeding();
    return 0;
}
