bool has_consistent_program(int n, const std::vector<std::string>& inputs,
                            const std::vector<int>& outputs) {
    const int m = static_cast<int>(inputs.size());
    std::vector<bool> active(m, true);
    int remaining = m;
    while (remaining > 0) {
        int common = -1;
        bool constant = true;
        for (int row = 0; row < m; ++row) {
            if (!active[row]) continue;
            if (common == -1) common = outputs[row];
            else if (common != outputs[row]) constant = false;
        }
        if (constant) return true;
        bool removed = false;
        for (int bit = 0; bit < n && !removed; ++bit) {
            for (int value = 0; value <= 1 && !removed; ++value) {
                int label = -1;
                bool pure = true;
                for (int row = 0; row < m; ++row) {
                    if (!active[row] || inputs[row][bit] - '0' != value) continue;
                    if (label == -1) label = outputs[row];
                    else if (label != outputs[row]) pure = false;
                }
                if (label == -1 || !pure) continue;
                for (int row = 0; row < m; ++row) {
                    if (active[row] && inputs[row][bit] - '0' == value) {
                        active[row] = false;
                        --remaining;
                    }
                }
                removed = true;
            }
        }
        if (!removed) return false;
    }
    return true;
}

void read_and_solve_reverse() {
    int tests;
    std::cin >> tests;
    while (tests--) {
        int n, m;
        std::cin >> n >> m;
        std::vector<std::string> inputs(m);
        std::vector<int> outputs(m);
        for (int row = 0; row < m; ++row) std::cin >> inputs[row] >> outputs[row];
        std::cout << (has_consistent_program(n, inputs, outputs) ? "OK" : "LIE") << '\n';
    }
}

